#!/usr/bin/env python3
import argparse,json
from pathlib import Path
def main():
 p=argparse.ArgumentParser();p.add_argument('--config',required=True);p.add_argument('--evidence',required=True);p.add_argument('--output-json',required=True);p.add_argument('--output-md',required=True);a=p.parse_args();d=json.load(open(a.evidence)); checks={'real_model_ready':d['entry_decision']=='REAL_MODEL_READY','checkpoint_hash_verified':d['checkpoint_hash_verified'],'real_prediction_verified':d['real_prediction_verified'],'oracle_path_gap':d['oracle_path_normalized_gap']<=.1,'learned_path_gap':d['learned_path_probe_normalized_gap']<=.25,'failure_negative':d['failure_negative_rate']>=.7,'recovery_positive':d['recovery_positive_rate']>=.65,'recovery_coverage':d['recovery_positive_weight_coverage']>=.3,'cycle_nonpositive':d['recovery_cycle_nonpositive_rate']>=.9,'positive_loop':d['positive_loop_rate']<=.05,'loop_mean':d['loop_return_mean']<=0,'success_margin':d['success_minus_failure_return_margin']>0 and (d['success_return_spearman']>=.35 or d['success_return_auroc'] not in ('not_estimable','')),'fixed_order':d['fixed_order_score_drop']<=.05,'reward_finite':not d['reward_nonfinite'],'lock':d['selection_locked']}; decision='GO_STAGE6' if all(checks.values()) else ('REFINE_STAGE5' if sum(not x for x in checks.values())<=1 else 'NO_GO_GRAPH_REWARD'); out={'decision':decision,'checks':checks,'statistics_unit':'content_group_id'};Path(a.output_json).parent.mkdir(parents=True,exist_ok=True);Path(a.output_json).write_text(json.dumps(out,indent=2));Path(a.output_md).write_text('# Stage 5 Exit Decision\n\n- `G2 = %s`\n- checks passed: `%d/%d`\n- selection lock was fixed before test evaluation.\n- statistics unit: `content_group_id`\n'%(decision,sum(checks.values()),len(checks)))
if __name__=='__main__':main()
